const ProcessAnimation: React.FC<AnimationProps> = ({
  backgroundColor = "#FAF9F6",
  transparentBackground = false,
  durationInSeconds = 10, // Included as required by schema, overall comp manages it
  gridColor = "#E5E5E5",
  accentColor = "#0055FF",
  iconBaseColor = "#888888",
  textColor = "#111111",
  steps = [
    { label: "PLANNING", iconType: "clipboard" },
    { label: "DESIGN", iconType: "design" },
    { label: "NEGOTIATION", iconType: "handshake" },
    { label: "BUILDING", iconType: "building" }
  ]
}) => {
  const frame = useCurrentFrame();
  const { fps, width } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  
  // Calculate a responsive base scale unit based on 1080x1920
  const responsiveScale = width / 1080;

  // Timings: 1.5 seconds stagger between each item appearing
  const staggerFrames = Math.round(1.5 * fps);
  const initialDelay = 15;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily }}>
      {/* Background Grid Pattern */}
      {!transparentBackground && (
        <AbsoluteFill style={{ opacity: 0.7 }}>
          <svg width="100%" height="100%">
            <defs>
              <pattern
                id="faint-grid"
                width={80 * responsiveScale}
                height={80 * responsiveScale}
                patternUnits="userSpaceOnUse"
              >
                <path
                  d={`M ${80 * responsiveScale} 0 L 0 0 0 ${80 * responsiveScale}`}
                  fill="none"
                  stroke={gridColor}
                  strokeWidth={1 * responsiveScale}
                />
              </pattern>
            </defs>
            <rect width="100%" height="100%" fill="url(#faint-grid)" />
          </svg>
        </AbsoluteFill>
      )}

      {/* Content Vertical Stack */}
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          width: "100%",
          height: "100%",
          gap: `${80 * responsiveScale}px`,
        }}
      >
        {steps.map((step, index) => {
          const startFrame = initialDelay + index * staggerFrames;
          
          // Animation calculations for each step
          const progress = spring({
            frame: frame - startFrame,
            fps,
            config: { damping: 14, mass: 0.8 }
          });

          const opacity = interpolate(
            frame,
            [startFrame, startFrame + 15],
            [0, 1],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          const yOffset = interpolate(progress, [0, 1], [40 * responsiveScale, 0]);
          const scale = interpolate(progress, [0, 1], [0.85, 1]);

          return (
            <div
              key={index}
              style={{
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                justifyContent: "center",
                opacity,
                transform: `translateY(${yOffset}px) scale(${scale})`,
                transition: "none",
                gap: `${24 * responsiveScale}px`
              }}
            >
              <div
                style={{
                  width: `${140 * responsiveScale}px`,
                  height: `${140 * responsiveScale}px`,
                }}
              >
                <IconRenderer
                  type={step.iconType}
                  baseColor={iconBaseColor}
                  accentColor={accentColor}
                />
              </div>
              <span
                style={{
                  fontSize: `${48 * responsiveScale}px`,
                  fontWeight: 600,
                  color: textColor,
                  letterSpacing: "0.06em",
                  textTransform: "uppercase"
                }}
              >
                {step.label}
              </span>
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default ProcessAnimation;